@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#17263a;--muted:#758196;--paper:#f7f5ef;--yellow:#f6cb49;--green:#73b89b;--line:#e4e6e2;--navy:#101c2d}
*{box-sizing:border-box}html{background:var(--navy)}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 42% 0%,#26364a 0,#101c2d 62%);color:var(--ink);font-family:'DM Sans',system-ui,sans-serif}.shell{width:min(1120px,calc(100% - 48px));margin:0 auto;padding:24px 0 18px}.topbar{height:48px;display:flex;align-items:center;justify-content:space-between;color:#f4f1e7;margin-bottom:23px}.brand{display:flex;gap:10px;align-items:center;color:inherit;text-decoration:none;font-size:13px;font-weight:600;letter-spacing:1.35px}.brand b{color:var(--yellow);font-weight:800}.brand-mark{display:grid;place-items:center;width:29px;height:29px;border:1px solid #576274;color:var(--yellow);font-size:17px;border-radius:8px}.edition{font:10px 'DM Mono',monospace;letter-spacing:1.5px;color:#aab3c0}.edition-dot,.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#93d3a6;margin-right:8px;vertical-align:1px;box-shadow:0 0 8px #93d3a6}.edition-sep{color:#626f81;margin:0 7px}.sound-toggle{background:transparent;color:#bec6d0;border:1px solid #435064;border-radius:5px;padding:8px 11px;font:11px 'DM Mono',monospace;cursor:pointer}.sound-toggle:hover{border-color:var(--yellow);color:#fff}.game-layout{display:grid;grid-template-columns:minmax(0,746px) minmax(270px,1fr);gap:19px;align-items:stretch}.game-column{min-width:0}.game-frame{border-radius:8px;background:#f8f6ef;padding:11px;box-shadow:0 20px 50px #080f1c80;border:1px solid #c8c8bc}.screen-top,.screen-bottom{height:26px;display:flex;align-items:center;justify-content:space-between;padding:0 6px;font:9px 'DM Mono',monospace;letter-spacing:1.3px;color:#6b7480}.screen-top{height:22px;padding-bottom:5px}.screen-bottom{height:25px;padding-top:5px;letter-spacing:.7px;text-transform:uppercase}.pixel-heart{font-size:15px;color:#e48c67}.canvas-wrap{position:relative;width:100%;aspect-ratio:16/9;background:#91c9a1;overflow:hidden;border:4px solid #293849;box-shadow:inset 0 0 0 1px #ffffff45}.canvas-wrap canvas{display:block;width:100%;height:100%;image-rendering:pixelated;image-rendering:crisp-edges}.screen-grain{pointer-events:none;position:absolute;inset:0;background:repeating-linear-gradient(0deg,#17263a0a 0px,#17263a0a 1px,transparent 1px,transparent 3px);opacity:.2}.controls-row{display:flex;align-items:center;gap:14px;padding:13px 2px 0;min-height:89px}.dpad{width:63px;height:63px;position:relative;display:grid;grid-template-columns:repeat(3,21px);grid-template-rows:repeat(3,21px);flex:none}.dpad-btn{border:0;background:#27374b;color:#f5f2e9;font-size:10px;line-height:1;cursor:pointer;touch-action:none;padding:0}.dpad-btn:hover,.dpad-btn:active{background:#46596e;color:var(--yellow)}.dpad-btn.up{grid-column:2;grid-row:1;border-radius:4px 4px 0 0}.dpad-btn.left{grid-column:1;grid-row:2;border-radius:4px 0 0 4px}.dpad-btn.right{grid-column:3;grid-row:2;border-radius:0 4px 4px 0}.dpad-btn.down{grid-column:2;grid-row:3;border-radius:0 0 4px 4px}.dpad-center{background:#27374b;grid-column:2;grid-row:2}.control-hint{flex:1;color:#aeb8c5;font:10px/1.9 'DM Mono',monospace;max-width:225px}.keycap{color:#e8e7de;background:#2c3b4e;border-radius:3px;padding:3px 4px;font-size:9px;white-space:nowrap}.hint-dot{color:#78889b;padding:0 3px}.action-button{height:46px;min-width:144px;margin-left:auto;border:0;border-radius:5px;background:var(--yellow);color:#293449;font:700 10px 'DM Mono',monospace;letter-spacing:.6px;padding:0 11px;display:flex;align-items:center;gap:7px;cursor:pointer;box-shadow:0 3px 0 #c6a337;transition:transform .1s,box-shadow .1s}.action-button:hover{background:#ffda62;transform:translateY(-1px);box-shadow:0 4px 0 #c6a337}.action-button:active{transform:translateY(2px);box-shadow:0 1px 0 #c6a337}.action-icon{font-size:17px}.action-key{border-left:1px solid #aa902d;padding-left:8px;margin-left:4px;font-size:8px;color:#665a32}.side-panel{border:1px solid #394658;background:#17263a;border-radius:8px;padding:19px 17px;color:#ece9df;display:flex;flex-direction:column;min-height:100%}.panel-kicker,.goal-label{font:9px 'DM Mono',monospace;letter-spacing:1.6px;color:#9daabc}.partner-card{display:flex;gap:13px;margin:17px 0 15px;align-items:center}.partner-art{width:83px;height:83px;position:relative;flex:none;border-radius:7px;background:#293b4c;display:grid;place-items:center;overflow:hidden;background-image:radial-gradient(#ffffff0e 1px,transparent 1px);background-size:8px 8px}.buddy-icon{position:relative;width:34px;height:35px;background:#f6c849;border:3px solid #d59b32;border-radius:48% 48% 43% 43%;box-shadow:inset -4px -3px #e8ad3d;z-index:2}.buddy-icon:before{content:'';position:absolute;width:13px;height:19px;left:-4px;top:-14px;background:#f4c747;clip-path:polygon(35% 0,100% 10%,100% 100%,0 100%);border-top:3px solid #d59b32}.buddy-icon:after{content:'';position:absolute;width:11px;height:21px;right:-4px;top:-14px;background:#f4c747;clip-path:polygon(0 10%,65% 0,100% 100%,0 100%);border-top:3px solid #d59b32}.ear{position:absolute;width:6px;height:7px;top:-9px;z-index:3;background:#302b2a}.e1{left:0;transform:rotate(-14deg)}.e2{right:0;transform:rotate(14deg)}.eye{position:absolute;width:3px;height:4px;background:#272b30;top:11px}.eye1{left:7px}.eye2{right:7px}.cheek{position:absolute;background:#ed735b;width:7px;height:6px;border-radius:50%;top:17px}.c1{left:-5px}.c2{right:-5px}.mouth{position:absolute;width:4px;height:2px;border-bottom:1px solid #573b2c;left:12px;top:20px}.spark{position:absolute;color:#f4cc56}.spark-a{top:12px;left:9px;font-size:13px}.spark-b{bottom:11px;right:9px;font-size:10px}.partner-info{flex:1;min-width:0}.partner-name{font-size:12px;font-weight:800;letter-spacing:.7px;color:#f8f4e8}.partner-name>span{float:right;color:#9ea9b7;font:9px 'DM Mono',monospace;margin-top:3px}.partner-name>span b{color:#f5cb4e}.partner-type{font:8px 'DM Mono',monospace;color:#aeb7c2;letter-spacing:1.1px;margin:5px 0 9px}.partner-type i{display:inline-block;width:6px;height:6px;background:#f2c74b;border-radius:50%;margin-right:5px}.hp-track{height:5px;background:#405064;border-radius:4px;overflow:hidden}.hp-fill{width:100%;height:100%;background:#8acb91;border-radius:4px;transition:width .25s}.hp-text{display:flex;justify-content:space-between;margin-top:5px;color:#8492a2;font:8px 'DM Mono',monospace}.hp-text b{font-weight:400;color:#d9e2dd}.stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.stat-box{padding:10px 11px;background:#223247;border-radius:5px;border:1px solid #304258}.stat-box span{display:block;color:#9eabba;font:8px 'DM Mono',monospace;letter-spacing:.8px}.stat-box b{display:inline-block;margin-top:5px;font:700 21px 'DM Mono',monospace;color:#f5cf54}.stat-box i{font-style:normal;color:#8090a1;font:9px 'DM Sans',sans-serif;margin-left:5px}.field-note{display:flex;gap:9px;margin:15px 0;background:#203044;padding:11px;border-left:2px solid #e6bd4b;border-radius:0 5px 5px 0}.note-icon{font-size:14px;color:#e6bd4b}.field-note b{font:8px 'DM Mono',monospace;letter-spacing:1px;color:#e8c85b}.field-note p{font-size:10px;line-height:1.5;color:#b3bdc8;margin:5px 0 0}.goal-box{padding:11px 1px 0;border-top:1px solid #354355;margin-top:auto}.goal-label{font-size:8px}.goal-text{display:flex;gap:8px;align-items:center;font-size:11px;color:#e4e7df;margin:9px 0}.goal-check{font:16px 'DM Mono',monospace;color:#e9c653}.goal-progress{height:3px;background:#36475a;border-radius:3px;overflow:hidden}.goal-progress div{height:100%;width:14%;background:#efca54;transition:width .4s}.side-footer{font:9px 'DM Sans',sans-serif;color:#7e8d9f;margin-top:14px}.side-footer span{color:#edc84f;margin-right:4px}.page-footer{display:flex;justify-content:space-between;margin-top:23px;color:#758397;font:8px 'DM Mono',monospace;letter-spacing:1.3px}.page-footer b{color:#f0c84b;font-size:13px;vertical-align:-1px}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);opacity:0;transition:.25s;pointer-events:none;background:#f8f5e9;color:#233249;padding:10px 15px;border-radius:5px;font:11px 'DM Mono',monospace;box-shadow:0 6px 25px #0005;z-index:10}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.shell{width:min(700px,calc(100% - 28px));padding-top:14px}.game-layout{grid-template-columns:1fr}.side-panel{min-height:0}.goal-box{margin-top:0}.side-footer{margin-top:11px}.game-frame{padding:8px}.edition{font-size:8px}.controls-row{gap:9px}.control-hint{font-size:9px}.action-button{min-width:128px}}
@media(max-width:480px){.shell{width:calc(100% - 20px);padding-top:10px}.topbar{margin-bottom:13px;height:39px}.edition{display:none}.brand{font-size:11px}.game-frame{padding:5px}.screen-top,.screen-bottom{font-size:7px}.canvas-wrap{border-width:3px}.controls-row{min-height:75px;gap:7px;padding-top:8px}.dpad{transform:scale(.88);transform-origin:left center;width:56px}.control-hint{font-size:8px;line-height:2}.keycap{font-size:7px;padding:3px}.action-button{min-width:105px;height:42px;font-size:8px;padding:0 7px;gap:4px}.action-key{font-size:7px;padding-left:5px;margin-left:2px}.side-panel{padding:15px}.partner-art{width:70px;height:70px}.page-footer{font-size:7px;letter-spacing:.6px;margin-top:15px}.page-footer span:last-child{text-align:right}}

(() => {
  'use strict';
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, T = 16;
  const $ = id => document.getElementById(id);
  const ui = {status:$('status-line'),area:$('area-label'),level:$('level'),hpBar:$('hp-bar'),hpText:$('hp-text'),buddyCount:$('buddy-count'),wins:$('win-count'),noteTitle:$('note-title'),note:$('field-note'),goal:$('goal-text'),goalCheck:$('goal-check'),progress:$('goal-progress'),action:$('action-label'),toast:$('toast')};
  const rnd = (a,b) => Math.floor(Math.random()*(b-a+1))+a;
  const clamp = (v,a,b) => Math.max(a,Math.min(b,v));
  const creatures = [
    {name:'MOSSLET',kind:'LEAF',color:'#79bd83',accent:'#3d8d62',hp:20},
    {name:'EMBERCUB',kind:'FLAME',color:'#ee9870',accent:'#d8644e',hp:22},
    {name:'PEBBLIT',kind:'STONE',color:'#aaa6a0',accent:'#817a74',hp:24},
    {name:'CLOUDFIN',kind:'MIST',color:'#9cc9d7',accent:'#568ca5',hp:19},
  ];
  const game = {
    mode:'title', step:0, steps:0, wins:0, caught:0, potions:2, level:3, xp:0,
    maxHp:28, hp:28, x:12, y:17, facing:'down', moveClock:0, buddyTrail:[],
    toastTimer:0, message:'A bright new day is waiting.', talked:false, quest:false,
    battle:null, sound:true, keys:{}, lastTime:0, anim:0, grassEncounterCooldown:0
  };
  const mapW=32,mapH=26;
  const path = new Set();
  const addPath=(x1,y1,x2,y2)=>{let x=x1,y=y1;path.add(`${x},${y}`);while(x!==x2){x+=Math.sign(x2-x);path.add(`${x},${y}`)}while(y!==y2){y+=Math.sign(y2-y);path.add(`${x},${y}`)}};
  addPath(12,19,12,8);addPath(12,12,20,12);addPath(12,16,5,16);addPath(20,12,25,12);
  const grassAreas=[{x:21,y:7,w:8,h:4},{x:23,y:13,w:6,h:7},{x:4,y:19,w:7,h:5},{x:16,y:4,w:5,h:3}];
  const ponds=[{x:25,y:3,w:5,h:3},{x:2,y:7,w:4,h:3}];
  const solids=new Set();
  for(let x=0;x<mapW;x++){solids.add(`${x},0`);solids.add(`${x},${mapH-1}`)}
  for(let y=0;y<mapH;y++){solids.add(`0,${y}`);solids.add(`${mapW-1},${y}`)}
  const buildings=[{x:8,y:4,w:6,h:4,type:'lab'},{x:3,y:13,w:5,h:3,type:'home'},{x:17,y:16,w:5,h:3,type:'home'}];
  buildings.forEach(b=>{for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++)solids.add(`${x},${y}`)});
  // Trees around the village make a soft, explorable boundary rather than a maze.
  const trees=[[2,3],[3,3],[4,3],[6,4],[7,4],[15,3],[16,3],[17,3],[18,3],[19,3],[20,3],[22,3],[23,3],[24,3],[3,5],[6,7],[7,7],[15,8],[16,8],[17,8],[18,8],[19,8],[29,5],[29,6],[29,7],[30,7],[2,11],[3,11],[4,11],[5,11],[9,9],[10,9],[28,21],[29,21],[30,21],[12,23],[13,23],[14,23],[15,23],[16,23],[17,23],[18,23],[19,23],[20,23],[21,23],[22,23],[23,23],[24,23],[25,23],[26,23],[27,23],[28,23],[29,23]];
  trees.forEach(([x,y])=>solids.add(`${x},${y}`));
  const npc={x:15,y:12};

  function tileType(x,y){
    if(x<0||y<0||x>=mapW||y>=mapH)return 'wall';
    if(ponds.some(p=>x>=p.x&&x<p.x+p.w&&y>=p.y&&y<p.y+p.h))return 'water';
    if(path.has(`${x},${y}`))return 'path';
    if(grassAreas.some(p=>x>=p.x&&x<p.x+p.w&&y>=p.y&&y<p.y+p.h))return 'tall';
    return 'grass';
  }
  function solid(x,y){return solids.has(`${x},${y}`)||tileType(x,y)==='water'||(x===npc.x&&y===npc.y)}
  function tone(hex,factor){const n=parseInt(hex.slice(1),16),r=clamp((n>>16)+factor,0,255),g=clamp(((n>>8)&255)+factor,0,255),b=clamp((n&255)+factor,0,255);return `rgb(${r},${g},${b})`}
  function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
  function pixelText(text,x,y,size=8,color='#fff',align='left'){ctx.font=`${size}px monospace`;ctx.textAlign=align;ctx.textBaseline='top';ctx.fillStyle=color;ctx.fillText(text,Math.round(x),Math.round(y))}
  function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}

  function drawTerrain(tx,ty,sx,sy){
    const type=tileType(tx,ty),seed=(tx*92821+ty*68917)%97;
    if(type==='grass'){
      rect(sx,sy,T,T,seed%5===0?'#84c28d':'#8bc995');
      if(seed%7===0){rect(sx+3,sy+4,2,2,'#a5d6a0');rect(sx+11,sy+12,2,1,'#6eb67c')}
    }else if(type==='path'){
      rect(sx,sy,T,T,'#d7bd85');if(seed%4===0)rect(sx+((seed%9)+3),sy+5,2,2,'#c7aa72');if(seed%6===0)rect(sx+3,sy+12,3,1,'#e6d09e');
    }else if(type==='tall'){
      rect(sx,sy,T,T,'#79bb80');
      let sway=Math.sin(game.anim*.003+tx*2+ty)*1.5;
      rect(sx+3,sy+9+sway,2,6,'#438e5c');rect(sx+5,sy+5+sway,2,9,'#519f66');rect(sx+9,sy+8-sway,2,7,'#3f8858');rect(sx+12,sy+4-sway,2,10,'#55a56c');rect(sx+4,sy+5+sway,2,2,'#9bd296');rect(sx+11,sy+4-sway,2,2,'#a1d89a');
    }else if(type==='water'){
      rect(sx,sy,T,T,'#78bbcf');rect(sx,sy,16,2,'#9cdaeb');if(seed%3===0){rect(sx+4,sy+8+Math.sin(game.anim*.002+tx)*2,5,1,'#a8e0e9');rect(sx+10,sy+12,2,1,'#639fb7')}
    }else rect(sx,sy,T,T,'#83bd8b');
  }

  function drawTree(x,y){
    const sx=x*T,sy=y*T;
    rect(sx+6,sy+9,5,8,'#875d42');rect(sx+4,sy+14,9,3,'#76513e');
    rect(sx+1,sy+5,14,7,'#39895c');rect(sx+3,sy+2,10,8,'#4b9b66');rect(sx+5,sy,6,6,'#5aa873');
    rect(sx+4,sy+4,2,2,'#82c585');rect(sx+11,sy+7,2,2,'#65b477');
  }
  function drawBuilding(b,cameraX,cameraY){
    const x=b.x*T-cameraX,y=b.y*T-cameraY,w=b.w*T,h=b.h*T;
    rect(x+3,y+8,w,h-7,'#d7c6a2');rect(x,y+5,w,7,b.type==='lab'?'#d96f55':'#d78363');
    for(let i=0;i<b.w;i++){rect(x+i*T+1,y+5,7,5,b.type==='lab'?'#e98764':'#e39a71')}
    rect(x+6,y+14,w-12,h-19,'#f1dfbd');rect(x+w/2-5,y+h-17,10,17,'#896248');rect(x+w/2-3,y+h-14,2,2,'#f4d36a');
    if(b.type==='lab'){
      rect(x+w/2-12,y+23,24,17,'#5e9fb2');rect(x+w/2-9,y+26,18,11,'#bde6d9');rect(x+w/2-10,y+38,20,2,'#42788b');
      rect(x+5,y+18,10,10,'#71a9b5');rect(x+7,y+20,6,6,'#b9e6d8');rect(x+w-15,y+18,10,10,'#71a9b5');rect(x+w-13,y+20,6,6,'#b9e6d8');
      rounded(x+w/2-23,y-3,46,12,3,'#fff2c7');pixelText('FIELD LAB',x+w/2,y,7,'#566477','center');
    }else{rect(x+6,y+18,15,12,'#72aab4');rect(x+8,y+20,11,8,'#bce3d6');rect(x+w-21,y+18,15,12,'#72aab4');rect(x+w-19,y+20,11,8,'#bce3d6')}
    rect(x+w/2-12,y+h-1,24,2,'#d2b37b');
  }

  function drawPerson(px,py,type,frame=0){
    const x=Math.round(px),y=Math.round(py);
    if(type==='hero'){
      // soft shadow, red cap, blue jacket and a tiny backpack
      rect(x-6,y+9,13,3,'#4b785d');rect(x-5,y-8,10,9,'#f0c79c');rect(x-6,y-11,12,5,'#c9544f');rect(x-4,y-15,9,5,'#d86054');rect(x+3,y-11,5,2,'#a63e44');
      rect(x-6,y,12,8,'#547fa1');rect(x-8,y+1,3,7,'#e2ad45');rect(x-4,y+2,3,4,'#d5e0dc');
      rect(x-5,y+7,4,5,'#40526b');rect(x+2,y+7,4,5,'#40526b');if(frame%2){rect(x-7,y+11,4,2,'#37465c');rect(x+2,y+11,4,2,'#37465c')}
      if(game.facing==='up'){rect(x-4,y-7,8,7,'#c78c66');rect(x-6,y-11,12,4,'#c9544f')}
    }else if(type==='prof'){
      rect(x-6,y+9,13,3,'#648966');rect(x-5,y-7,10,9,'#f2c99e');rect(x-7,y-10,14,5,'#f0f0dd');rect(x-7,y-4,14,13,'#f2f0df');rect(x-5,y+7,4,5,'#697c91');rect(x+2,y+7,4,5,'#697c91');rect(x-4,y-5,8,2,'#acb8b2');
    }
  }
  function drawVolt(px,py,scale=1){
    ctx.save();ctx.translate(Math.round(px),Math.round(py));ctx.scale(scale,scale);
    rect(-7,8,15,3,'#54825e');
    // lightning-bolt tail
    rect(7,0,4,3,'#e8b63d');rect(10,-4,3,5,'#e8b63d');rect(12,-7,4,5,'#e8b63d');rect(14,-9,4,3,'#e8b63d');
    // ears, body and cheeks
    rect(-7,-12,14,16,'#f2c849');rect(-5,-15,4,6,'#f2c849');rect(2,-15,4,6,'#f2c849');rect(-5,-16,3,3,'#34302e');rect(3,-16,3,3,'#34302e');
    rect(-8,-4,3,4,'#e76a56');rect(5,-4,3,4,'#e76a56');rect(-3,-8,2,3,'#282c32');rect(2,-8,2,3,'#282c32');rect(-1,-3,2,1,'#77503a');
    rect(-5,3,4,4,'#dfa83c');rect(2,3,4,4,'#dfa83c');rect(-4,7,3,3,'#8e6844');rect(2,7,3,3,'#8e6844');
    ctx.restore();
  }

input.newString:
  ctx.restore();
}

function drawMap(){
  const camX=clamp(game.x*T-W/2+8,0,mapW*T-W),camY=clamp(game.y*T-H/2+8,0,mapH*T-H);
  const startX=Math.floor(camX/T),startY=Math.floor(camY/T);
  for(let ty=startY;ty<=startY+H/T;ty++)for(let tx=startX;tx<=startX+W/T;tx++)drawTerrain(tx,ty,tx*T-camX,ty*T-camY);
  // Tiny flowers and stepping stones add a little life to the quiet town.
  for(let y=startY;y<=startY+H/T;y++)for(let x=startX;x<=startX+W/T;x++){
    if(tileType(x,y)==='grass'&&(x*7+y*13)%31===0){rect(x*T-camX+7,y*T-camY+8,2,2,'#f3d16a');rect(x*T-camX+9,y*T-camY+7,2,2,'#fff0c1')}
  }
  buildings.forEach(b=>drawBuilding(b,camX,camY));
  trees.forEach(([x,y])=>drawTree(x*T-camX,y*T-camY));
  // A little fence around the lab garden.
  for(let x=14;x<19;x++){const fx=x*T-camX,fy=10*T-camY;rect(fx,fy,2,8,'#ae8858');rect(fx+7,fy,2,8,'#ae8858');rect(fx,fy+2,9,2,'#c29a66')}
  const npcX=npc.x*T+8-camX,npcY=npc.y*T+8-camY;
  if(npcX>-10&&npcX<W+10)drawPerson(npcX,npcY,'prof',game.anim>>8);
  // Draw the companion a half-step behind the trainer.
  const buddy=game.buddyTrail[0]||{x:game.x,y:game.y+1};
  drawVolt(buddy.x*T+8-camX,buddy.y*T+8-camY,.72);
  drawPerson(game.x*T+8-camX,game.y*T+8-camY,'hero',game.anim>>7);
  // Area plaque and proximity hints.
  const inTrail=game.x>19||game.y>18;
  rounded(7,7,92,17,3,'#26384cdd');pixelText(inTrail?'SUNMEADOW TRAIL':'SUNMEADOW TOWN',12,12,7,'#fff3d4');
  if(Math.abs(game.x-npc.x)+Math.abs(game.y-npc.y)<=2){rounded(240,190,136,18,3,'#26384cdd');pixelText('SPACE  ·  TALK TO PROF.',248,196,7,'#fff3d4')}
  if(game.x>=20&&game.y>=7&&game.y<=20){rounded(276,7,99,17,3,'#26384cdd');pixelText('TALL GRASS  ✦',283,12,7,'#d7f0bc')}
}

function drawTitle(){
  rect(0,0,W,H,'#79bb92');
  // dreamy meadow, layered hills and flowers
  rect(0,126,W,90,'#75b783');rect(0,145,W,71,'#69aa7c');
  for(let i=0;i<12;i++){const x=i*38-10;rect(x,72+(i%3)*7,42,66,'#89c995');rect(x+8,58+(i%3)*7,28,25,'#89c995');rect(x+15,48+(i%3)*7,17,15,'#89c995')}
